    // ── DeltaNet ops (feature-gated) ─────────────────────────────────────

    /// Split a fused interleaved `[n_patches, 3 * hidden]` QKV buffer
    /// into three separate `[n_patches, hidden]` Q, K, V buffers.
    /// Used by the dots.ocr vision encoder when feeding the
    /// non-causal `attention_dflash_f32` kernel (which expects Q/K/V
    /// as separate flat buffers).
    ///
    /// `hidden` here is `n_heads * head_dim` — the second axis of each
    /// of Q, K, V within the fused buffer.
    pub fn qkv_split_interleaved_f32(
        &mut self,
        qkv: &GpuTensor,
        q: &GpuTensor,
        k: &GpuTensor,
        v: &GpuTensor,
        n_patches: usize,
        hidden: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        assert!(
            n_patches > 0,
            "qkv_split_interleaved_f32: n_patches must be > 0"
        );
        assert!(hidden > 0, "qkv_split_interleaved_f32: hidden must be > 0");
        self.ensure_kernel(
            "qkv_split_interleaved",
            kernels::QKV_SPLIT_INTERLEAVED_SRC,
            "qkv_split_interleaved_f32",
        )?;

        let qkvp = qkv.buf.as_ptr();
        let qp = q.buf.as_ptr();
        let kp = k.buf.as_ptr();
        let vp = v.buf.as_ptr();
        let np = n_patches as i32;
        let hd = hidden as i32;

        let mut params: Vec<*mut c_void> = vec![
            &qkvp as *const _ as *mut c_void,
            &qp as *const _ as *mut c_void,
            &kp as *const _ as *mut c_void,
            &vp as *const _ as *mut c_void,
            &np as *const _ as *mut c_void,
            &hd as *const _ as *mut c_void,
        ];

        let block_size = 256u32;
        let grid_y = ((hidden as u32) + block_size - 1) / block_size;
        let grid = [n_patches as u32, grid_y, 1];
        let block = [block_size, 1, 1];
        // Bytes-touched estimate: 3 reads + 3 writes per (patch, j) thread.
        let bytes = n_patches * hidden * 4 * 6;
        let timer =
            crate::profile::begin_timer(&self.hip, "qkv_split", "qkv_split_interleaved_f32", bytes);
        let result = self.launch_maybe_blob(
            "qkv_split_interleaved_f32",
            grid,
            block,
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(qkvp);
                b.push_ptr(qp);
                b.push_ptr(kp);
                b.push_ptr(vp);
                b.push_i32(np);
                b.push_i32(hd);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// In-place F32 → bf16 → F32 round-trip on `x`. Used by the
    /// dots.ocr vision encoder for HF-bf16-precision emulation
    /// (see `kernels/src/bf16_round_trip.hip`).
    pub fn bf16_round_trip_f32(&mut self, x: &GpuTensor) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "bf16_round_trip",
            kernels::BF16_ROUND_TRIP_SRC,
            "bf16_round_trip_f32",
        )?;
        let xp = x.buf.as_ptr();
        let n = x.numel() as i32;
        let mut params: Vec<*mut c_void> = vec![
            &xp as *const _ as *mut c_void,
            &n as *const _ as *mut c_void,
        ];
        let block_size = 256u32;
        let grid = (((n as u32) + block_size - 1) / block_size).max(1);
        let bytes = crate::profile::elementwise_bytes(n as usize);
        let timer =
            crate::profile::begin_timer(&self.hip, "bf16_round_trip", "bf16_round_trip_f32", bytes);
        let result = self.launch_maybe_blob(
            "bf16_round_trip_f32",
            [grid, 1, 1],
            [block_size, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(xp);
                b.push_i32(n);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Deinterleave: split [A_h0(hd), B_h0(hd), A_h1(hd), B_h1(hd), ...] into A and B.
    /// Replaces per-head memcpy loop (n_heads × 2 ioctls → 1 dispatch).
    pub fn deinterleave_f32(
        &mut self,
        interleaved: &GpuTensor,
        out_a: &GpuTensor,
        out_b: &GpuTensor,
        n_heads: usize,
        head_dim: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "deinterleave",
            kernels::DEINTERLEAVE_SRC,
            "deinterleave_f32",
        )?;
        let inp = interleaved.buf.as_ptr();
        let ap = out_a.buf.as_ptr();
        let bp = out_b.buf.as_ptr();
        let nh = n_heads as i32;
        let hd = head_dim as i32;
        let mut params: Vec<*mut c_void> = vec![
            &inp as *const _ as *mut c_void,
            &ap as *const _ as *mut c_void,
            &bp as *const _ as *mut c_void,
            &nh as *const _ as *mut c_void,
            &hd as *const _ as *mut c_void,
        ];
        let total = (n_heads * head_dim) as u32;
        let block = 256u32;
        let grid = (total + block - 1) / block;
        let bytes = n_heads * head_dim * 4 * 3; // read interleaved, write both outputs
        let timer =
            crate::profile::begin_timer(&self.hip, "elementwise", "deinterleave_f32", bytes);
        let result = self.launch_maybe_blob(
            "deinterleave_f32",
            [grid, 1, 1],
            [block, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(inp);
                b.push_ptr(ap);
                b.push_ptr(bp);
                b.push_i32(nh);
                b.push_i32(hd);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Batched deinterleave: split [N × n_heads × head_dim × 2] interleaved
    /// Q+Gate into separate [N × n_heads × head_dim] Q and Gate tensors.
    /// Replaces the per-token gather/deinterleave/scatter loop in the FA
    /// batched prefill path.
    pub fn deinterleave_f32_batched(
        &mut self,
        interleaved: &GpuTensor,
        out_q: &GpuTensor,
        out_gate: &GpuTensor,
        n_heads: usize,
        head_dim: usize,
        n: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "deinterleave_batched",
            kernels::DEINTERLEAVE_BATCHED_SRC,
            "deinterleave_f32_batched",
        )?;
        let mut inp = interleaved.buf.as_ptr();
        let mut qp = out_q.buf.as_ptr();
        let mut gp = out_gate.buf.as_ptr();
        let mut nh = n_heads as i32;
        let mut hd = head_dim as i32;
        let mut nn = n as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut inp as *mut _ as *mut c_void,
            &mut qp as *mut _ as *mut c_void,
            &mut gp as *mut _ as *mut c_void,
            &mut nh as *mut _ as *mut c_void,
            &mut hd as *mut _ as *mut c_void,
            &mut nn as *mut _ as *mut c_void,
        ];
        let total = (n_heads * head_dim) as u32;
        let block = 256u32;
        let grid_x = (total + block - 1) / block;
        let bytes = n * n_heads * head_dim * 4 * 3;
        let timer = crate::profile::begin_timer(
            &self.hip,
            "elementwise",
            "deinterleave_f32_batched",
            bytes,
        );
        let result = self.launch_maybe_blob(
            "deinterleave_f32_batched",
            [grid_x, n as u32, 1],
            [block, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(inp);
                b.push_ptr(qp);
                b.push_ptr(gp);
                b.push_i32(nh);
                b.push_i32(hd);
                b.push_i32(nn);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Softplus activation, in-place.
    #[cfg(feature = "deltanet")]
    pub fn softplus_f32(&mut self, x: &GpuTensor) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel("softplus", kernels::SOFTPLUS_SRC, "softplus_f32")?;
        let func = &self.functions["softplus_f32"];
        let mut xp = x.buf.as_ptr();
        let mut n = x.numel() as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut xp as *mut _ as *mut c_void,
            &mut n as *mut _ as *mut c_void,
        ];
        let block = 256u32;
        let grid = ((n as u32) + block - 1) / block;
        unsafe {
            self.hip.launch_kernel(
                func,
                [grid, 1, 1],
                [block, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        }
    }

    /// L2 normalization per head, in-place. One warp per head.
    #[cfg(feature = "deltanet")]
    pub fn l2_norm_f32(
        &mut self,
        x: &GpuTensor,
        n_heads: usize,
        head_dim: usize,
        eps: f32,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel("l2_norm", kernels::L2_NORM_SRC, "l2_norm_f32")?;
        let func = &self.functions["l2_norm_f32"];
        let mut xp = x.buf.as_ptr();
        let mut nh = n_heads as i32;
        let mut hd = head_dim as i32;
        let mut ep = eps;
        let mut params: Vec<*mut c_void> = vec![
            &mut xp as *mut _ as *mut c_void,
            &mut nh as *mut _ as *mut c_void,
            &mut hd as *mut _ as *mut c_void,
            &mut ep as *mut _ as *mut c_void,
        ];
        let bytes = crate::profile::elementwise1_bytes(n_heads * head_dim);
        let timer = crate::profile::begin_timer(&self.hip, "rmsnorm", "l2_norm_f32", bytes);
        let result = unsafe {
            self.hip.launch_kernel(
                func,
                [n_heads as u32, 1, 1],
                [32, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        };
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Exact per-row/per-2048-token chunk top-256 + logsumexp stats for
    /// KLD reference generation. The caller merges the emitted chunk
    /// candidates across chunks/tiles on the host.
    pub fn kld_tile_topk_lse_f32(
        &mut self,
        logits: &GpuTensor,
        top_vals: &GpuTensor,
        top_idx: &GpuTensor,
        chunk_max: &GpuTensor,
        chunk_sum: &GpuTensor,
        batch_size: usize,
        vocab_tile: usize,
        global_start: usize,
        n_chunks: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "kld_tile_topk_lse",
            kernels::KLD_TILE_TOPK_LSE_SRC,
            "kld_tile_topk_lse_f32",
        )?;
        let func = &self.functions["kld_tile_topk_lse_f32"];
        let lp = logits.buf.as_ptr();
        let vp = top_vals.buf.as_ptr();
        let ip = top_idx.buf.as_ptr();
        let mp = chunk_max.buf.as_ptr();
        let sp = chunk_sum.buf.as_ptr();
        let mut bi = batch_size as i32;
        let mut vi = vocab_tile as i32;
        let mut gi = global_start as i32;
        let mut ci = n_chunks as i32;
        let mut params: Vec<*mut c_void> = vec![
            &lp as *const _ as *mut c_void,
            &vp as *const _ as *mut c_void,
            &ip as *const _ as *mut c_void,
            &mp as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &mut bi as *mut _ as *mut c_void,
            &mut vi as *mut _ as *mut c_void,
            &mut gi as *mut _ as *mut c_void,
            &mut ci as *mut _ as *mut c_void,
        ];
        let bytes = batch_size * vocab_tile * 4
            + batch_size * n_chunks * 256 * 8
            + batch_size * n_chunks * 2 * 4;
        let timer = crate::profile::begin_timer(&self.hip, "kld", "kld_tile_topk_lse_f32", bytes);
        let result = unsafe {
            self.hip.launch_kernel(
                func,
                [batch_size as u32, n_chunks as u32, 1],
                [256, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        };
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    /// Validate the fixed tile shape used by the current Gated DeltaNet HIP kernels.
    #[cfg(feature = "deltanet")]
    fn ensure_gdn_hd128(head_dim: usize) -> HipResult<()> {
        if head_dim == 128 {
            Ok(())
        } else {
            Err(hip_bridge::HipError::new(
                0,
                &format!(
                    "Gated DeltaNet kernels are currently specialized for head_dim=128; got {head_dim}. \
                     Add a matching HD-specialized kernel or generalize the kernel before dispatching this shape."
                ),
            ))
        }
    }

    #[cfg(feature = "deltanet")]
    fn gdn_q8_reg_gfx1151_enabled(&self) -> bool {
        static ENABLED: OnceLock<bool> = OnceLock::new();
        let enabled = *ENABLED.get_or_init(|| {
            // HIPFIRE_GDN_Q8_REG_GFX1151=1 enables the gfx1151 register-state
            // GDN Q8 probe. Default off after A3B pp256 prefill regressed
            // 11.8ms -> 168.5ms total GDN time.
            std::env::var("HIPFIRE_GDN_Q8_REG_GFX1151").as_deref() == Ok("1")
        });
        enabled && self.arch.starts_with("gfx1151")
    }

    /// Scale vector by constant: x[i] *= scale. Replaces 48µs CPU roundtrip.
    #[cfg(feature = "deltanet")]
    pub fn scale_f32(&mut self, x: &GpuTensor, scale: f32) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel("scale_f32", kernels::SCALE_F32_SRC, "scale_f32")?;
        let func = &self.functions["scale_f32"];
        let n = x.numel();
        let mut xp = x.buf.as_ptr();
        let mut nv = n as i32;
        let mut sv = scale;
        let mut params: Vec<*mut c_void> = vec![
            &mut xp as *mut _ as *mut c_void,
            &mut nv as *mut _ as *mut c_void,
            &mut sv as *mut _ as *mut c_void,
        ];
        let block = 256u32;
        let grid = ((n as u32) + block - 1) / block;
        let bytes = crate::profile::elementwise1_bytes(n);
        let timer = crate::profile::begin_timer(&self.hip, "elementwise", "scale_f32", bytes);
        let result = unsafe {
            self.hip.launch_kernel(
                func,
                [grid, 1, 1],
                [block, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        };
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result
    }

    #[cfg(feature = "deltanet")]
    #[allow(clippy::too_many_arguments)]
    fn conv1d_silu_split_f32_n_gfx1151(
        &mut self,
        q_out: &GpuTensor,
        k_out: &GpuTensor,
        v_out: &GpuTensor,
        input: &GpuTensor,
        weight: &GpuTensor,
        state: &GpuTensor,
        k_dim: usize,
        v_dim: usize,
        n_tokens: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "conv1d_silu_split_gfx1151",
            kernels::CONV1D_SILU_SPLIT_GFX1151_SRC,
            "conv1d_silu_split_f32_gfx1151",
        )?;
        self.ensure_kernel(
            "conv1d_silu_split_state_gfx1151",
            kernels::CONV1D_SILU_SPLIT_GFX1151_SRC,
            "conv1d_silu_split_update_state_gfx1151",
        )?;

        let qp = q_out.buf.as_ptr();
        let kp = k_out.buf.as_ptr();
        let vp = v_out.buf.as_ptr();
        let ip = input.buf.as_ptr();
        let wp = weight.buf.as_ptr();
        let sp = state.buf.as_ptr();
        let kd = k_dim as i32;
        let vd = v_dim as i32;
        let nt = n_tokens as i32;
        let mut params: Vec<*mut c_void> = vec![
            &qp as *const _ as *mut c_void,
            &kp as *const _ as *mut c_void,
            &vp as *const _ as *mut c_void,
            &ip as *const _ as *mut c_void,
            &wp as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &kd as *const _ as *mut c_void,
            &vd as *const _ as *mut c_void,
            &nt as *const _ as *mut c_void,
        ];
        let n_channels = 2 * k_dim + v_dim;
        let block = 256u32;
        let grid = ((n_channels as u32) + block - 1) / block;
        let bytes = crate::profile::conv1d_silu_bytes(n_channels) * n_tokens;
        let timer = crate::profile::begin_timer(
            &self.hip,
            "deltanet",
            "conv1d_silu_split_f32_n_gfx1151",
            bytes,
        );
        let result = self.launch_maybe_blob(
            "conv1d_silu_split_f32_gfx1151",
            [grid, n_tokens as u32, 1],
            [block, 1, 1],
            0,
            &mut params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(qp);
                b.push_ptr(kp);
                b.push_ptr(vp);
                b.push_ptr(ip);
                b.push_ptr(wp);
                b.push_ptr(sp);
                b.push_i32(kd);
                b.push_i32(vd);
                b.push_i32(nt);
                b
            },
        );
        if let Some(t) = timer {
            t.finish(&self.hip);
        }
        result?;

        let nc = n_channels as i32;
        let mut update_params: Vec<*mut c_void> = vec![
            &ip as *const _ as *mut c_void,
            &sp as *const _ as *mut c_void,
            &nc as *const _ as *mut c_void,
            &nt as *const _ as *mut c_void,
        ];
        let update_bytes = n_channels * 4 * 4;
        let update_timer = crate::profile::begin_timer(
            &self.hip,
            "deltanet",
            "conv1d_silu_split_state_gfx1151",
            update_bytes,
        );
        let update_result = self.launch_maybe_blob(
            "conv1d_silu_split_update_state_gfx1151",
            [grid, 1, 1],
            [block, 1, 1],
            0,
            &mut update_params,
            || {
                let mut b = hip_bridge::KernargBlob::new();
                b.push_ptr(ip);
                b.push_ptr(sp);
                b.push_i32(nc);
                b.push_i32(nt);
                b
            },
        );
        if let Some(t) = update_timer {
            t.finish(&self.hip);
        }
        update_result
    }

    /// Compute cross-entropy loss for a single token on GPU.
    /// Returns -log(softmax(logits)[target]). Downloads 4 bytes instead of 600KB.
    pub fn cross_entropy_loss(
        &mut self,
        logits: &GpuTensor,
        target_buf: &DeviceBuffer,
        loss_buf: &GpuTensor,
        vocab_size: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "cross_entropy_loss",
            kernels::CROSS_ENTROPY_LOSS_SRC,
            "cross_entropy_loss",
        )?;
        let func = &self.functions["cross_entropy_loss"];
        let mut lp = logits.buf.as_ptr();
        let mut tp = target_buf.as_ptr();
        let mut op = loss_buf.buf.as_ptr();
        let mut vs = vocab_size as i32;
        let mut params: Vec<*mut c_void> = vec![
            &mut lp as *mut _ as *mut c_void,
            &mut tp as *mut _ as *mut c_void,
            &mut op as *mut _ as *mut c_void,
            &mut vs as *mut _ as *mut c_void,
        ];
        let block_size = 256u32;
        let shared_mem = (block_size * 4) as u32;
        unsafe {
            self.hip.launch_kernel(
                func,
                [1, 1, 1],
                [block_size, 1, 1],
                shared_mem,
                self.stream_ref(),
                &mut params,
            )
        }
    }

