    /// int4-quantized activation. `group` must be 256.
    #[allow(clippy::too_many_arguments)]
    pub fn gemv_oq4_grouped(
        &mut self,
        w_i4: &GpuTensor,
        w_scales: &GpuTensor,
        x_i4: &GpuTensor,
        x_scales: &GpuTensor,
        y_f32: &GpuTensor,
        m: usize,
        k: usize,
        group: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        assert_eq!(group, 256, "gemv_oq4_grouped: group must be 256");
        assert_eq!(
            k % group,
            0,
            "gemv_oq4_grouped: K must be a multiple of group"
        );
        self.ensure_kernel(
            "gemv_oq4_grouped",
            kernels::GEMV_OQ4_GROUPED_SRC,
            "gemv_oq4_grouped",
        )?;
        let wp = w_i4.buf.as_ptr();
        let wsp = w_scales.buf.as_ptr();
        let xp = x_i4.buf.as_ptr();
        let xsp = x_scales.buf.as_ptr();
        let yp = y_f32.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut gi = group as i32;
        let mut params: Vec<*mut c_void> = vec![
            &wp as *const _ as *mut c_void,
            &wsp as *const _ as *mut c_void,
            &xp as *const _ as *mut c_void,
            &xsp as *const _ as *mut c_void,
            &yp as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
            &mut gi as *mut _ as *mut c_void,
        ];
        let func = &self.functions["gemv_oq4_grouped"];
        unsafe {
            self.hip.launch_kernel(
                func,
                [m as u32, 1, 1],
                [32, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        }
    }

    /// Reference kernel layer: expand packed int4 weights `wp_i4` [M,K/2] → int8
    /// `w8_i8` [M,K] (sign-extended), the W4A8 input to the iu8 WMMA core.
    pub fn nibble_expand_int4_to_int8(
        &mut self,
        wp_i4: &GpuTensor,
        w8_i8: &GpuTensor,
        m: usize,
        k: usize,
    ) -> HipResult<()> {
        self.bind_thread()?;
        self.ensure_kernel(
            "nibble_expand_int4_to_int8",
            kernels::NIBBLE_EXPAND_INT4_TO_INT8_SRC,
            "nibble_expand_int4_to_int8",
        )?;
        let pp = wp_i4.buf.as_ptr();
        let op = w8_i8.buf.as_ptr();
        let mut mi = m as i32;
        let mut ki = k as i32;
        let mut params: Vec<*mut c_void> = vec![
            &pp as *const _ as *mut c_void,
            &op as *const _ as *mut c_void,
            &mut mi as *mut _ as *mut c_void,
            &mut ki as *mut _ as *mut c_void,
        ];
        let n = m * k;
        let grid = ((n + 255) / 256) as u32;
        let func = &self.functions["nibble_expand_int4_to_int8"];
        unsafe {
            self.hip.launch_kernel(
                func,
                [grid, 1, 1],
                [256, 1, 1],
                0,
                self.stream_ref(),
                &mut params,
            )
        }
    }

